-- 0115 — Clasificacion inicial de Monare; motor reutilizable en 0114.
-- Aplicada via MCP el 24/oct/2026.
-- Usa pertenencias existentes de cat_groups y nombres/presentaciones del catalogo.
-- Conserva categorias legacy, precios, disponibilidad, imagenes y descripciones.
-- Skin Contact queda en Vinos hasta confirmar estilo; envases 3L siguen pendientes.
-- No hay declaraciones Vegano/Sin TACC hasta recibir el listado de la clienta.

do $monare_facets$
declare affected integer;
begin
  with incoming as (
    select * from jsonb_to_recordset('[{"name":"Ancestral Blend - Caja x3","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Ancestral","varietal":"Blend","presentation":"Caja de madera x3"}},{"name":"Ancestral Malbec - Caja x3","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Ancestral","varietal":"Malbec","presentation":"Caja de madera x3"}},{"name":"Ancestral White Blend - Caja x3","catalog_attributes":{"category":"Vinos blancos","features":[],"brand":"Mauricio Lorca","line":"Ancestral","varietal":"Blend","presentation":"Caja de madera x3"}},{"name":"Chandon Extra Brut","catalog_attributes":{"category":"Espumantes","features":[],"brand":"Chandon","presentation":"Botella"}},{"name":"Cosecha Especial Rosé","catalog_attributes":{"category":"Espumantes","features":[],"presentation":"Botella"}},{"name":"Cosecha Tardía Rosé","catalog_attributes":{"category":"Espumantes","features":[],"presentation":"Botella"}},{"name":"Fantasía Cabernet Franc","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Fantasía","varietal":"Cabernet Franc","presentation":"Botella"}},{"name":"Fantasía Cabernet Sauvignon","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Fantasía","varietal":"Cabernet Sauvignon","presentation":"Botella"}},{"name":"Fantasía Cabernet Sauvignon - Caja x6","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Fantasía","varietal":"Cabernet Sauvignon","presentation":"Caja x6"}},{"name":"Fantasía Chardonnay","catalog_attributes":{"category":"Vinos blancos","features":[],"brand":"Mauricio Lorca","line":"Fantasía","varietal":"Chardonnay","presentation":"Botella"}},{"name":"Fantasía Chardonnay - Caja x6","catalog_attributes":{"category":"Vinos blancos","features":[],"brand":"Mauricio Lorca","line":"Fantasía","varietal":"Chardonnay","presentation":"Caja x6"}},{"name":"Fantasía Criolla Tinta","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Fantasía","varietal":"Criolla Tinta","presentation":"Botella"}},{"name":"Fantasía Malbec","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Fantasía","varietal":"Malbec","presentation":"Botella"}},{"name":"Fantasía Sauvignon Blanc","catalog_attributes":{"category":"Vinos blancos","features":[],"brand":"Mauricio Lorca","line":"Fantasía","varietal":"Sauvignon Blanc","presentation":"Botella"}},{"name":"Fantasía Torrontés","catalog_attributes":{"category":"Vinos blancos","features":[],"brand":"Mauricio Lorca","line":"Fantasía","varietal":"Torrontés","presentation":"Botella"}},{"name":"Freixenet Dulce","catalog_attributes":{"category":"Espumantes","features":[],"brand":"Freixenet","presentation":"Botella"}},{"name":"Gran Ópalo Blend","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Gran Ópalo","varietal":"Blend","presentation":"Botella"}},{"name":"Grandes Varietales Blend","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Grandes Varietales","varietal":"Blend","presentation":"Botella"}},{"name":"Grandes Varietales Malbec","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Grandes Varietales","varietal":"Malbec","presentation":"Botella"}},{"name":"Grandes Varietales Petit Verdot","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Grandes Varietales","varietal":"Petit Verdot","presentation":"Botella"}},{"name":"Hielo 15 kg - Lote de 15 bolsas","catalog_attributes":{"category":"Hielo","features":[],"presentation":"Lote de 15 bolsas de 15 kg"}},{"name":"Hielo 15 kg - Lote de 30 bolsas","catalog_attributes":{"category":"Hielo","features":[],"presentation":"Lote de 30 bolsas de 15 kg"}},{"name":"Hielo 2 kg - Lote de 15 bolsas","catalog_attributes":{"category":"Hielo","features":[],"presentation":"Lote de 15 bolsas de 2 kg"}},{"name":"Hielo 2 kg - Lote de 30 bolsas","catalog_attributes":{"category":"Hielo","features":[],"presentation":"Lote de 30 bolsas de 2 kg"}},{"name":"Inspirado Blend 3000 ml","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Inspirado","varietal":"Blend","presentation":"3 litros (envase por confirmar)"}},{"name":"Inspirado Blend 750 ml","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Inspirado","varietal":"Blend","presentation":"Botella de 750 ml"}},{"name":"Inspirado Cab. Cab. 750 ml","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Inspirado","varietal":"Blend","presentation":"Botella de 750 ml"}},{"name":"Inspirado Cabernet Cabernet 3000 ml","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Inspirado","varietal":"Blend","presentation":"3 litros (envase por confirmar)"}},{"name":"Inspirado Cabernet Franc 3000 ml","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Inspirado","varietal":"Cabernet Franc","presentation":"3 litros (envase por confirmar)"}},{"name":"Inspirado Cabernet Franc 750 ml","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Inspirado","varietal":"Cabernet Franc","presentation":"Botella de 750 ml"}},{"name":"Inspirado Chardonnay 750 ml - Caja x3","catalog_attributes":{"category":"Vinos blancos","features":[],"brand":"Mauricio Lorca","line":"Inspirado","varietal":"Chardonnay","presentation":"Caja x3"}},{"name":"Lois Rosé","catalog_attributes":{"category":"Espumantes","features":[],"brand":"Mauricio Lorca","line":"Lois","varietal":"Malbec","presentation":"Botella"}},{"name":"Lois Rosé - Caja x6","catalog_attributes":{"category":"Espumantes","features":[],"brand":"Mauricio Lorca","line":"Lois","varietal":"Malbec","presentation":"Caja x6"}},{"name":"Lorca Joven Malbec","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Lorca Joven","varietal":"Malbec","presentation":"Botella"}},{"name":"Lorca Joven Malbec - Caja x6","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Lorca Joven","varietal":"Malbec","presentation":"Caja x6"}},{"name":"Mumm","catalog_attributes":{"category":"Espumantes","features":[],"brand":"Mumm","presentation":"Botella"}},{"name":"Natural Cabernet Franc - Malbec","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Natural","varietal":"Blend","presentation":"Botella"}},{"name":"Ópalo Cabernet Sauvignon","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Ópalo","varietal":"Cabernet Sauvignon","presentation":"Botella"}},{"name":"Ópalo Malbec","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Ópalo","varietal":"Malbec","presentation":"Botella"}},{"name":"Ópalo Semillón - Sauvignon Blanc","catalog_attributes":{"category":"Vinos blancos","features":[],"brand":"Mauricio Lorca","line":"Ópalo","varietal":"Semillón / Sauvignon Blanc","presentation":"Botella"}},{"name":"Ópalo Syrah","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Ópalo","varietal":"Syrah","presentation":"Botella"}},{"name":"Ópalo Syrah - Caja x6","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Ópalo","varietal":"Syrah","presentation":"Caja x6"}},{"name":"Poético Cabernet Franc","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Poético","varietal":"Cabernet Franc","presentation":"Botella"}},{"name":"Poético Cabernet Sauvignon","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Poético","varietal":"Cabernet Sauvignon","presentation":"Botella"}},{"name":"Poético Chardonnay","catalog_attributes":{"category":"Vinos blancos","features":[],"brand":"Mauricio Lorca","line":"Poético","varietal":"Chardonnay","presentation":"Botella"}},{"name":"Poético Malbec","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Poético","varietal":"Malbec","presentation":"Botella"}},{"name":"Poético Syrah","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Poético","varietal":"Syrah","presentation":"Botella"}},{"name":"Poético White Blend","catalog_attributes":{"category":"Vinos blancos","features":[],"brand":"Mauricio Lorca","line":"Poético","varietal":"Blend","presentation":"Botella"}},{"name":"Pulka Rosé","catalog_attributes":{"category":"Espumantes","features":[],"presentation":"Botella"}},{"name":"Salentein Extra Brut","catalog_attributes":{"category":"Espumantes","features":[],"brand":"Salentein","presentation":"Botella"}},{"name":"Skin Contact Viognier","catalog_attributes":{"category":"Vinos","features":[],"brand":"Mauricio Lorca","line":"Skin Contact","varietal":"Viognier","presentation":"Botella"}},{"name":"Zapam Zucum Orgánico Cabernet Sauvignon","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Zapam Zucum","varietal":"Cabernet Sauvignon","presentation":"Botella"}},{"name":"Zapam Zucum Orgánico Malbec","catalog_attributes":{"category":"Vinos tintos","features":[],"brand":"Mauricio Lorca","line":"Zapam Zucum","varietal":"Malbec","presentation":"Botella"}}]'::jsonb)
      as x(name text,catalog_attributes jsonb)
  )
  update public.products p set catalog_attributes=i.catalog_attributes from incoming i
  where p.tenant_id=(select id from public.tenants where slug='monare')
    and p.name=i.name and p.catalog_attributes='{}'::jsonb;
  get diagnostics affected=row_count;
  if affected<>53 then raise exception 'Clasificacion cancelada: se esperaban 53 productos, coincidieron %',affected; end if;
  update public.settings set catalog_profile='beverages'
  where tenant_id=(select id from public.tenants where slug='monare') and catalog_profile is null;
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'Perfil de Monare modificado en paralelo'; end if;
end $monare_facets$;
